### 3. `idempotency_and_storage_contract`

Per `KB-RES-02`, all write operations (`POST /api/kb/proposals`, `/approve`, `/reject`) use deterministic idempotency keys and single-transaction atomic commits followed by synchronous cache re-hydration.

```json
{
  "idempotency_and_storage_contract": {
    "deterministic_key_derivation": {
      "stage_proposal": "sha256('stage:' + proposed_by + ':' + action_type + ':' + id + ':' + canonicalJson(payload))",
      "approve_proposal": "sha256('approve:' + proposal_id + ':' + target_version)",
      "reject_proposal": "sha256('reject:' + proposal_id)",
      "ttl_seconds": 86400,
      "replay_behavior": "If Idempotency-Key exists AND payload_sha256 matches, return stored HTTP status and JSON body without re-executing write.",
      "mismatch_behavior": "If Idempotency-Key exists AND payload_sha256 differs, fail closed with 409 Conflict (IDEMPOTENCY_KEY_PAYLOAD_MISMATCH)."
    },
    "atomic_storage_transaction": {
      "isolation": "ACID database transaction (SERIALIZABLE / row-level FOR UPDATE lock) or mutex-guarded temp-file + fsync + atomic rename",
      "approve_sequence": [
        "1. Verify CHO RBAC token and Idempotency-Key record.",
        "2. Lock proposal row WHERE proposal_id = :id AND status = 'pending'. If not found or status != 'pending', abort with 409/404.",
        "3. Precondition check: if action_type == 'create', assert kb_id does not exist in live_kb (else 409 KB_ID_ALREADY_EXISTS). If action_type == 'update', assert kb_id exists and live_kb.version == target_version - 1 (else 409 VERSION_CONFLICT).",
        "4. Upsert live_kb (set version = target_version, updated_at = UTC ISO-8601).",
        "5. Update kb_proposals SET status = 'approved', decided_at = NOW(), decided_by = 'CHO'.",
        "6. Persist Idempotency-Key response snapshot.",
        "7. Commit transaction."
      ]
    },
    "immediate_kb_cache_refresh": {
      "strategy": "Synchronous write-through invalidation + re-hydration on commit",
      "steps": [
        "1. Immediately after DB commit succeeds, acquire cache write lock.",
        "2. Reload all live_kb entries from committed storage into in-memory/Redis cache.",
        "3. Recompute deterministic kb_etag = sha256(canonicalJson(live_kb_entries)).",
        "4. Emit internal 'kb.refreshed' event so active Director/Specialist contexts receive updated KB-* entries on next dispatch.",
        "5. Return 200 OK with cache_refreshed: true and new kb_etag."
      ],
      "failure_handling": "If DB commit fails, transaction rolls back and cache is untouched. If cache refresh throws after commit, log critical alert and mark cache dirty so next GET /api/kb forces synchronous reload from DB (fail-safe read-repair)."
    }
  }
}
```

